/**
 * Greyscale Asia Pacific map behind the "Our global pipeline" dots (inventory B21, DC §3): land only, no
 * borders or labels, in the 646 x 571 frame. Natural Earth 1:50m land (public domain, via world-atlas
 * 2.0.2) in Web Mercator, 57°E to 184.5°E, 50°N to about 48°S. `projectPipeline` turns a market's
 * longitude / latitude into its position on the frame, so the dots sit on their real markets.
 * Generated: do not edit the path by hand.
 */
export const PIPELINE_MAP_W = 646;
export const PIPELINE_MAP_H = 571;

const LON0 = 57;
const LON1 = 184.5;
const LAT_TOP = 50;

const merc = (lat: number) => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
const K = PIPELINE_MAP_W / (((LON1 - LON0) * Math.PI) / 180);

/** Longitude / latitude → position on the frame, as percentages (left, top). */
export function projectPipeline(lon: number, lat: number): { left: number; top: number } {
  const x = (((lon < -150 ? lon + 360 : lon) - LON0) * Math.PI) / 180 * K;
  const y = (merc(LAT_TOP) - merc(lat)) * K;
  return { left: (x / PIPELINE_MAP_W) * 100, top: (y / PIPELINE_MAP_H) * 100 };
}

